/* зазор точки (рамка грудной клетки) до гладкой оболочки рёбер вдоль луча от оси, см (+ снаружи) */
function ribGap(p){const x=Math.abs(p[0]),z=p[2]-RIB_ENV.zc;return Math.hypot(x,z)-ribSlide(p[1],Math.atan2(x,z)*R2D);}
